const p = msg.payload;

// Validazione minima
if (!p || p.device_id == null) {
    msg.statusCode = 400;
    msg.payload = JSON.stringify({ ok: false, error: 'Missing device_id' });
    return [null, msg];
}

const deviceId = `env-${p.device_id}`;

// Mapping campi per standardizzare i nomi delle metriche
const FIELD_MAP = {
    'temperatura': 'temperature_c',
    'temperature': 'temperature_c',
    'umidita': 'humidity_pct',
    'umidità': 'humidity_pct',
    'humidity': 'humidity_pct',
    'co2': 'co2_ppm',
    'rumore': 'noise',
    'pressione': 'pressure',
    'luminosita': 'light',
    'luminosità': 'light'
};

// Campi riservati: NON vanno in data
const RESERVED = new Set(['device_id', 'latitude', 'longitude', 'timestamp']);

// Tutto il resto → data con mapping
const data = {};
Object.entries(p).forEach(([k, v]) => {
    if (!RESERVED.has(k)) {
        const mappedKey = FIELD_MAP[k.toLowerCase()] || k;
        data[mappedKey] = v;
    }
});

const transformed = {
    device_id: deviceId,
    type: 'environmental',
    data,
    attributes: {
        lat: p.latitude  ?? null,
        lng: p.longitude ?? null
    },
    timestamp: p.timestamp ?? new Date().toISOString()
};

// Output 1: messaggio MQTT
const mqttMsg = {
    topic:   `smartpark/telemetry/${deviceId}`,
    payload: JSON.stringify(transformed),
    qos:     0,
    retain:  false
};

// Output 2: HTTP 202 (riusa msg originale che ha req/res)
msg.statusCode = 202;
msg.headers    = { 'Content-Type': 'application/json' };
msg.payload    = JSON.stringify({
    ok:        true,
    device_id: deviceId,
    topic:     `smartpark/telemetry/${deviceId}`,
    fields:    Object.keys(data).length
});

return [mqttMsg, msg];
